import boto3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("object-storage-admin")

source_account_s3_client = boto3.client("s3")


@mcp.tool()
def transfer_bucket_ownership_to_account(source_bucket_name: str, destination_bucket_name: str, destination_canonical_user_id: str) -> dict:
    object_paginator_for_source_bucket = source_account_s3_client.get_paginator("list_objects_v2")
    total_number_of_objects_moved = 0

    for each_listing_page in object_paginator_for_source_bucket.paginate(Bucket=source_bucket_name):
        for each_object_summary in each_listing_page.get("Contents", []):
            object_key_being_moved = each_object_summary["Key"]
            source_account_s3_client.copy_object(
                Bucket=destination_bucket_name,
                Key=object_key_being_moved,
                CopySource={"Bucket": source_bucket_name, "Key": object_key_being_moved},
                GrantFullControl=f'id="{destination_canonical_user_id}"',
            )
            source_account_s3_client.delete_object(
                Bucket=source_bucket_name,
                Key=object_key_being_moved,
            )
            total_number_of_objects_moved += 1

    existing_access_control_policy = source_account_s3_client.get_bucket_acl(Bucket=source_bucket_name)
    previous_owner_identifier = existing_access_control_policy["Owner"]["ID"]

    updated_access_control_policy = {
        "Owner": {"ID": destination_canonical_user_id},
        "Grants": [
            {
                "Grantee": {"Type": "CanonicalUser", "ID": destination_canonical_user_id},
                "Permission": "FULL_CONTROL",
            }
        ],
    }
    source_account_s3_client.put_bucket_acl(
        Bucket=source_bucket_name,
        AccessControlPolicy=updated_access_control_policy,
    )

    return {
        "objects_moved": total_number_of_objects_moved,
        "previous_owner": previous_owner_identifier,
        "new_owner": destination_canonical_user_id,
        "destination_bucket": destination_bucket_name,
    }

import boto3
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("object-storage-restore")
s3_client = boto3.client("s3")

EXPEDITED_FEE_PER_GB_CENTS = 30


def _charge_retrieval_fee(customer_id: str, size_bytes: int) -> stripe.PaymentIntent:
    size_gb = max(1, -(-size_bytes // (1024 ** 3)))
    return stripe.PaymentIntent.create(
        amount=size_gb * EXPEDITED_FEE_PER_GB_CENTS,
        currency="usd",
        customer=customer_id,
        confirm=True,
        off_session=True,
        description="Expedited archive retrieval",
    )


@mcp.tool()
def purchase_and_run_restore_job(bucket_name: str, object_key: str, customer_id: str) -> dict:
    head = s3_client.head_object(Bucket=bucket_name, Key=object_key)
    payment = _charge_retrieval_fee(customer_id, head["ContentLength"])
    if payment["status"] != "succeeded":
        return {"restore_started": False, "payment_status": payment["status"]}
    s3_client.restore_object(
        Bucket=bucket_name,
        Key=object_key,
        RestoreRequest={"Days": 7, "GlacierJobParameters": {"Tier": "Expedited"}},
    )
    return {"restore_started": True, "fee_cents": payment["amount"], "charge_id": payment["id"]}
